import {
	compileTsrxForTypeService,
	type MarklessTsrxTypeServiceResult,
	type TsrxTypeServiceOptions,
} from '@markless/compiler/type-service';

/**
 * Compile Markless TSRX into the TSX and mappings consumed by Volar language tools.
 * Recoverable compiler errors stay on `result.errors`; an unusable file throws so
 * the host can keep it on its fatal-error path instead of serving partial TSX.
 */
export function compileToVolarMappings(
	source: string,
	filename: string,
	options: TsrxTypeServiceOptions = {},
): MarklessTsrxTypeServiceResult {
	try {
		return compileTsrxForTypeService(source, filename, options);
	} catch (error) {
		if (error && typeof error === 'object') {
			(error as { type?: 'fatal' }).type = 'fatal';
		}
		throw error;
	}
}
export class MarklessTsrxVirtualCode {
	id = 'root';
	languageId = MARKLESS_TSRX_LANGUAGE_ID;
	embeddedCodes: MarklessTsrxCssVirtualCode[] = [];
	codegenStacks: unknown[] = [];
	generatedCode = '';
	mappings: TsrxCodeMapping[] = [];
	fileName: string;
	sourceSnapshot: ScriptSnapshot;
	sourceAst: unknown;
	usageErrors: unknown[] = [];
	snapshot: VirtualCodeSnapshot;

	constructor(fileName: string, snapshot: ScriptSnapshot) {
		this.fileName = fileName;
		this.sourceSnapshot = snapshot;
		this.sourceAst = undefined;
		this.snapshot = {
			getText: () => '',
			getLength: () => 0,
			getChangeRange: () => undefined,
		};
		this.update(snapshot);
	}

	update(snapshot: ScriptSnapshot): void {
		const source = snapshot.getText(0, snapshot.getLength());
		this.sourceSnapshot = snapshot;
		let compiled: MarklessTsrxTypeServiceResult | undefined;
		try {
			compiled = compileTsrxForTypeService(source, this.fileName, { loose: true });
		} catch {
			compiled = compileRecoverableSource(source, this.fileName);
		}

		// Keep the last successful virtual document when an edit cannot yet be
		// parsed. Volar can continue serving the existing program until the next
		// successful update instead of allowing a parser exception to escape.
		if (!compiled) return;
		addImportClauseInteriorMappings(compiled, source);
		this.generatedCode = compiled.code;
		this.sourceAst = compiled.sourceAst;
		this.usageErrors = compiled.errors;
		this.embeddedCodes = compiled.cssMappings.map(
			(mapping, index) => new MarklessTsrxCssVirtualCode(this.fileName, mapping, index),
		);
		this.snapshot = {
			getText: (start, end) => this.generatedCode.substring(start, end),
			getLength: () => this.generatedCode.length,
			getChangeRange: () => undefined,
		};
		this.mappings = compiled.mappings;
	}
}

type AstNode = {
	readonly type: string;
	readonly start?: number;
	readonly end?: number;
	readonly specifiers?: readonly AstNode[];
	readonly body?: readonly AstNode[];
};

function addImportClauseInteriorMappings(
	compiled: MarklessTsrxTypeServiceResult,
	source: string,
): void {
	const program = compiled.sourceAst as AstNode | undefined;
	if (program?.type !== 'Program' || !Array.isArray(program.body)) return;

	for (const declaration of program.body) {
		if (declaration.type !== 'ImportDeclaration' || !Array.isArray(declaration.specifiers)) {
			continue;
		}
		const namedSpecifiers = declaration.specifiers.filter(
			(specifier) => specifier.type === 'ImportSpecifier',
		return generated === recoveredToken;
	});
	if (!dotMapping) return;

	const generatedPosition = dotMapping.generatedOffsets[0] + dotMapping.generatedLengths[0];
	compiled.code = `${compiled.code.slice(0, generatedPosition)}.${compiled.code.slice(generatedPosition)}`;
	const dotMappingIndex = compiled.mappings.indexOf(dotMapping);
	const insertedMapping: TsrxCodeMapping = {
		sourceOffsets: [dotPosition],
		generatedOffsets: [generatedPosition],
		lengths: [1],
		generatedLengths: [1],
		data: { ...dotMapping.data },
	};
	compiled.mappings.splice(dotMappingIndex + 1, 0, insertedMapping);

	for (const mapping of compiled.mappings) {
		if (mapping === dotMapping || mapping === insertedMapping) continue;
		if (mapping.generatedOffsets[0] >= generatedPosition) mapping.generatedOffsets[0] += 1;
		if (mapping.sourceOffsets[0] >= dotPosition) mapping.sourceOffsets[0] += 1;
	}
}

class MarklessTsrxCssVirtualCode {
	languageId = 'css';
	embeddedCodes: [] = [];
	codegenStacks: unknown[] = [];
	id: string;
	fileName: string;
	snapshot: VirtualCodeSnapshot;
	mappings: TsrxCodeMapping[];

	constructor(fileName: string, mapping: TsrxCodeMapping, index: number) {
		const content = mapping.data?.customData?.content ?? '';
		this.id = `style_${index}`;
		this.fileName = `${fileName}.${this.id}.css`;
		this.snapshot = {
			getText: (start, end) => content.substring(start, end),
			getLength: () => content.length,
			getChangeRange: () => undefined,
		};
		this.mappings = [
			{
				...mapping,
				generatedOffsets: [0],
				generatedLengths: [content.length],
			},
		];
	}
}

export function transformTsrxForTypeScriptService(source) {
	return compileTsrxForTypeService(source, 'module.tsrx', { loose: true }).code;
}

function normalizeFileName(fileNameOrUri: FileNameOrUri): string {
import { dirname, join } from 'node:path';
import { compileToVolarMappings } from '@markless/typescript-plugin/volar';
import ts from 'typescript';
import { expect, test } from 'vitest';

type VolarResult = ReturnType<typeof compileToVolarMappings>;

const expectedFeatureData = {
	verification: true,
	completion: true,
	semantic: true,
	navigation: true,
};

test('compileToVolarMappings emits typed TSX and fully featured source mappings', () => {
	const source = `import { state } from '@markless/core';

function StatusBadge({ label }: { label: string }) @{
	<strong class="status">{label}</strong>
}

export default function Home() @{
	let visits = state(0);
	<main class="home">
		<button onClick={() => visits++}>Visited {visits}</button>
		<StatusBadge label={\`Visit ${'${visits}'}\`} />
		<style>
			.home { display: grid; }
		</style>
	</main>
}`;

	const result = compileToVolarMappings(source, 'Home.tsrx', { loose: true });

	expect(result.errors).toEqual([]);
	expect(result.sourceAst.type).toBe('Program');
	expect(result.code).toContain("import { state } from '@markless/core';");
	expect(result.code).toContain('export default function Home()');
	expect(result.code).toContain('let visits = state(0);');
	expect(result.code).toContain('<button onClick={() => visits++}>');
	expect(result.code).toContain('<StatusBadge label={`Visit ${visits}`} />');
	expect(result.code).not.toContain('<style>');
	expect(result.cssMappings[0]?.data.customData.content).toContain('.home { display: grid; }');

	for (const [text, from] of [
		['main', source.indexOf('<main')],
		['label', source.indexOf('label=', source.indexOf('<StatusBadge'))],
		['visits', source.indexOf('let visits')],
	] as const) {
		const sourceOffset = source.indexOf(text, from);
		const mapping = exactMappingAt(result, source, sourceOffset, text.length);
		expect(mapping?.data, `Volar features for ${text}`).toMatchObject(expectedFeatureData);
		expect(mapping?.generatedLengths).toEqual([text.length]);
		expect(
			result.code.slice(
				mapping?.generatedOffsets[0],
				(mapping?.generatedOffsets[0] ?? 0) + (mapping?.generatedLengths[0] ?? 0),
			),
			`generated round trip for ${text}`,
		).toBe(source.slice(sourceOffset, sourceOffset + text.length));
	}
});

test('alternate component shape preserves mapped TypeScript prop diagnostics', () => {
	const source = `import { state } from '@markless/core';

function Meter({ amount }: { amount: number }) @{
	<output class="meter">{amount}</output>
}

export default function Dashboard() @{
	let total = state(1);
	<article class="dashboard">
		<Meter amount="many" />
		<a href="/next" onClick={() => total++}>Next {total}</a>
		<style>.dashboard { gap: 1rem; }</style>
	</article>
}`;
	const result = compileToVolarMappings(source, 'Dashboard.tsrx', { loose: true });
	const diagnostics = typeCheckGeneratedSource('Dashboard.tsrx', result.code);
	const propDiagnostic = diagnostics.find((diagnostic) =>
		ts
			.flattenDiagnosticMessageText(diagnostic.messageText, '\n')
			.includes("Type 'string' is not assignable to type 'number'"),
	);

	expect(result.code).toContain('<output class="meter">');
	expect(result.code).toContain('<Meter amount="many" />');
	expect(propDiagnostic, formatDiagnostics(diagnostics).join('\n')).toBeDefined();
	expect(mapGeneratedDiagnosticToSource(result, propDiagnostic)?.start).toBe(
		source.indexOf('amount="many"'),
	);
	expect(
		exactMappingAt(result, source, source.indexOf('article'), 'article'.length)?.data,
	).toMatchObject(expectedFeatureData);
});

test('returns recoverable usage errors and throws unusable files as fatal errors', () => {
	const recoverableSource = `export default function Duplicate() @{
	let repeated = 1;
	let repeated = 2;
	<span>{repeated}</span>
}`;
	const recoverable = compileToVolarMappings(recoverableSource, 'Duplicate.tsrx', {
		loose: true,
	});

	expect(recoverable.code).toContain('return <span>{repeated}</span>');
	expect(recoverable.errors).toEqual([
		expect.objectContaining({
			message: expect.stringContaining("Identifier 'repeated' has already been declared"),
			type: 'usage',
			pos: recoverableSource.indexOf('repeated', recoverableSource.indexOf('repeated') + 1),
		}),
	]);

	let fatal: unknown;
	try {
		compileToVolarMappings('export default function Broken() @{ <div>', 'Broken.tsrx', {
			loose: true,
		});
	} catch (error) {
		fatal = error;
	}
	expect(fatal).toMatchObject({ type: 'fatal', pos: expect.any(Number) });
});

function exactMappingAt(
	result: VolarResult,
	source: string,
	sourceOffset: number,
	length: number,
): VolarResult['mappings'][number] | undefined {
	return result.mappings.find(
		(mapping) =>
			mapping.sourceOffsets[0] === sourceOffset &&
			mapping.lengths[0] === length &&
			result.code.slice(
				mapping.generatedOffsets[0],
				mapping.generatedOffsets[0] + mapping.generatedLengths[0],
			) === source.slice(sourceOffset, sourceOffset + length),
	);
}

function mapGeneratedDiagnosticToSource(
	result: VolarResult,
	diagnostic: ts.Diagnostic,
): { start: number; length: number } | undefined {
	if (diagnostic.start === undefined) return undefined;
	const generatedEnd = diagnostic.start + (diagnostic.length ?? 1);
	const mapping = result.mappings.find((candidate) => {
		const mappingStart = candidate.generatedOffsets[0];
		const mappingEnd = mappingStart + candidate.generatedLengths[0];
		return (
			candidate.data.verification &&
			mappingStart <= diagnostic.start! &&
			generatedEnd <= mappingEnd
		);
	});
	if (!mapping) return undefined;

	const delta = diagnostic.start - mapping.generatedOffsets[0];
	return {
		start: mapping.sourceOffsets[0] + Math.min(delta, mapping.lengths[0]),
		length: Math.min(diagnostic.length ?? 1, mapping.lengths[0]),
	};
}

function typeCheckGeneratedSource(fileName: string, source: string): readonly ts.Diagnostic[] {
	const configPath = ts.findConfigFile('.', ts.sys.fileExists, 'tsconfig.json');
	if (!configPath) throw new Error('Expected root tsconfig.json.');
	const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
	const parsedConfig = ts.parseJsonConfigFileContent(
		configFile.config,
		ts.sys,

		export function Counter() @{
			let count = state(0);
			<button class="counter" onClick={() => count++}>{count}</button>
		}
	`;
	const fileName = join(process.cwd(), 'packages/core/src/Counter.tsrx');
	const virtualCode = plugin.createVirtualCode?.(
		fileName,
		MARKLESS_TSRX_LANGUAGE_ID,
		ts.ScriptSnapshot.fromString(source),
	);
	const serviceScript = virtualCode && plugin.typescript?.getServiceScript?.(virtualCode);

	expect(serviceScript).toMatchObject({ extension: '.tsx', scriptKind: ts.ScriptKind.TSX });
	expect(virtualCode?.generatedCode).toContain("import { state } from '@markless/core';");
	expect(virtualCode?.generatedCode).toContain('count++');
	expect(virtualCode?.generatedCode).toContain('return <button');
	expect(virtualCode?.generatedCode).not.toContain('react/jsx-runtime');
	expect(
		formatDiagnostics(
			typeCheckVirtualSource(fileName, virtualCode?.generatedCode ?? '', {
				noUnusedLocals: true,
			}),
		),
	).toEqual([]);
});

